import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatMain.css";

const ChatMain = ({ user, conversation }) => {
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");

  useEffect(() => {
    const fetchMessages = async () => {
      if (!conversation?._id) return;
      try {
        const res = await axios.get(`http://localhost:5000/api/messages/${conversation._id}`);
        setMessages(res.data);
      } catch (err) {
        console.error("Error fetching messages:", err);
      }
    };

    fetchMessages();
  }, [conversation]);

  const handleSend = async () => {
    if (!newMessage.trim()) return;

    try {
      const res = await axios.post("http://localhost:5000/api/messages", {
        conversationId: conversation._id,
        senderId: user.userId,
        senderUsername: user.username,
        receiverId: conversation.participants.find(id => id !== user.userId),
        receiverUsername: conversation.participantUsernames.find(name => name !== user.username),
        text: newMessage,
      });

      setMessages([...messages, res.data]);
      setNewMessage("");
    } catch (err) {
      console.error("Error sending message:", err);
    }
  };

  if (!conversation) {
    return <div className="chat-main"><p>No conversation selected</p></div>;
  }

  return (
    <div className="chat-main">
      <div className="chat-messages">
        {messages.map((msg) => (
          <div
            key={msg._id}
            className={`message-bubble ${msg.senderId === user.userId ? "sent" : "received"}`}
          >
            <p>{msg.text}</p>
            <span className="timestamp">
              {new Date(msg.timestamp).toLocaleString()}
            </span>
          </div>
        ))}
      </div>
      <div className="chat-input">
        <input
          type="text"
          placeholder="Type your message..."
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && handleSend()}
        />
        <button onClick={handleSend}>Send</button>
      </div>
    </div>
  );
};

export default ChatMain;
